SPRITE_V = ""  # версия спрайта (хэш содержимого) — выставляется в write_sprite


def icon(name, cls="i"):
    """Иконка как ссылка на общий спрайт: браузер скачивает все иконки один раз и кэширует,
    а страница становится в несколько раз легче, чем со встроенными SVG."""
    if name not in ICONS:
        name = "circle"
    if not SPRITE_V:  # спрайт ещё не записан (скрипты, тесты без запуска сервера) — встраиваем как раньше
        return Markup(f'<svg class="{cls}" viewBox="0 0 24 24" aria-hidden="true">{ICONS[name]}</svg>')
    return Markup(f'<svg class="{cls}" viewBox="0 0 24 24" aria-hidden="true"><use href="/static/icons.svg?v={SPRITE_V}#{name}"/></svg>')


def glyph(value, cls="i in"):
    """Значок из базы: имя иконки → SVG-иконка, эмодзи (старые записи, выбор пользователя) → SVG-эмодзи."""
    if not value:
        return Markup("")
    if value in ICONS:
        return icon(value, cls)
    from services.text import emoji_img
    return emoji_img(value)


def reaction(value):
    """Реакция на сообщение/историю: сердце и кит — свои иконки, старые эмодзи — SVG-эмодзи."""
    if value in ("❤️", "❤", "heart"):
        return Markup(f'<span class="rx rx-heart">{icon("heart-fill", "i")}</span>')
    if value in ("🐋", "whale"):
        return Markup(f'<span class="rx rx-whale">{icon("whale-fill", "i")}</span>')
    return glyph(value)


def sprite():
    parts = [f'<symbol id="{k}" viewBox="0 0 24 24">{v}</symbol>' for k, v in ICONS.items()]
    return '<svg xmlns="http://www.w3.org/2000/svg" style="display:none">' + "".join(parts) + "</svg>"


def write_sprite(path):
    """Пишет static/icons.svg, если он устарел (вызывается при старте сервера)."""
    global SPRITE_V
    import hashlib
    data = sprite()
    SPRITE_V = hashlib.sha1(data.encode()).hexdigest()[:8]
    try:
        with open(path, encoding="utf-8") as f:
            if f.read() == data:
                return
    except OSError:
        pass
    with open(path, "w", encoding="utf-8") as f:
        f.write(data)
